(function($) {
    // alert('Attaching handlers started!');
    const HAS_MN_TARGET_SEL = '[data-mn-toggle]';
    function toggler_handler() {
        let $el: JQuery<HTMLElement> = $(this);
        let targets = $el.attr('data-mn-target')!;
        let css_class = $el.attr('data-mn-toggle')!;
        $(targets).toggleClass(css_class);
        console.warn(`${targets} : ${css_class}`);
    }
    $('main').on('click', HAS_MN_TARGET_SEL, toggler_handler);
})(jQuery);

